/**
 * Unit tests for MutableDateTime#addDays
 */
public class MutableDateTime_addDays_TriageGen0Test {

    @Test
    public void testAddDaysPositive() {
        // Arrange: Set a specific date (2023-01-01)
        MutableDateTime dt = new MutableDateTime(2023, 1, 1, 12, 0, 0, 0);

        // Act: Add 5 days
        dt.addDays(5);

        // Assert: Should be 2023-01-06
        assertEquals(2023, dt.getYear());
        assertEquals(1, dt.getMonthOfYear());
        assertEquals(6, dt.getDayOfMonth());
    }












}

